package com.fasterxml.jackson.databind.ser.std;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.BeanProperty;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.jsonFormatVisitors.*;
import com.fasterxml.jackson.databind.ser.ContextualSerializer;
import com.fasterxml.jackson.databind.ser.std.StdDateFormat;
import com.fasterxml.jackson.databind.util.StdDateFormat;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Type;
import java.math.*;
import java.text.DateFormat;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Locale;
import java.util.TimeZone;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

/**
 * Unit tests for DateTimeSerializerBase#createContextual.
 * Since DateTimeSerializerBase is abstract, we use a concrete test implementation.
 */
public class DateTimeSerializerBase_createContextual_TriageGen1Test {

    private TestDateTimeSerializer testSerializer;
    private SerializerProvider mockSerializers;
    private BeanProperty mockProperty;

    // Concrete implementation for testing abstract class
    private static class TestDateTimeSerializer extends DateTimeSerializerBase<java.util.Date> {
        private final Boolean useTimestamp;
        private final DateFormat customFormat;

        protected TestDateTimeSerializer(Class<java.util.Date> type, Boolean useTimestamp, DateFormat customFormat) {
            super(type, useTimestamp, customFormat);
            this.useTimestamp = useTimestamp;
            this.customFormat = customFormat;
        }

        @Override
        public JsonSerializer<?> withFormat(Boolean useTimestamp, DateFormat customFormat) {
            return new TestDateTimeSerializer(java.util.Date.class, useTimestamp, customFormat);
        }

        @Override
        public boolean isEmpty(java.util.Date value) { return value == null; }

        @Override
        public boolean isEmpty(SerializerProvider serializers, java.util.Date value) { return value == null; }

        @Override
        protected long _timestamp(java.util.Date value) { return value.getTime(); }

        @Override
        public void serialize(java.util.Date value, com.fasterxml.jackson.core.JsonGenerator gen, SerializerProvider serializers) throws java.io.IOException {
        }

        @Override
        protected boolean _asTimestamp(SerializerProvider serializers) { return useTimestamp; }

        @Override
        protected void _acceptJsonFormatVisitor(com.fasterxml.jackson.databind.ser.std.JsonFormatVisitorWrapper visitor, com.fasterxml.jackson.databind.JavaType typeHint, boolean asNumber) throws JsonMappingException {
        }

        @Override
        public com.fasterxml.jackson.databind.JsonNode getSchema(SerializerProvider serializers, com.fasterxml.jackson.databind.JavaType typeHint) { return null; }

        // Mocking findFormatOverrides which is usually part of the base logic
        // In actual Jackson, this is a protected method. Since we can't override it easily 
        // if it's final or logic-heavy, we simulate the behavior via the test class.
        // However, the provided code shows findFormatOverrides is called. 
        // We must ensure the test subclass can simulate the return values.
        private JsonFormat.Value mockFormat;

        public void setMockFormat(JsonFormat.Value format) {
            this.mockFormat = format;
        }

        @Override
        protected JsonFormat.Value findFormatOverrides(SerializerProvider serializers, BeanProperty property, com.fasterxml.jackson.databind.JavaType baseType) {
            return mockFormat;
        }
    }

    @Before
    public void setUp() {
        testSerializer = new TestDateTimeSerializer(java.util.Date.class, false, null);
        mockSerializers = mock(SerializerProvider.class);
        mockProperty = mock(BeanProperty.class);

        // Default mocks for serializers
        when(mockSerializers.getLocale()).thenReturn(Locale.US);
        when(mockSerializers.getTimeZone()).thenReturn(TimeZone.getTimeZone("UTC"));
    }

    @Test
    public void testCreateContextual_PropertyNull() throws JsonMappingException {
        JsonSerializer<?> result = testSerializer.createContextual(mockSerializers, null);
        assertSame("Should return this if property is null", testSerializer, result);
    }

    @Test
    public void testCreateContextual_FormatNull() throws JsonMappingException {
        testSerializer.setMockFormat(null);
        JsonSerializer<?> result = testSerializer.createContextual(mockSerializers, mockProperty);
        assertSame("Should return this if format is null", testSerializer, result);
    }

    @Test
    public void testCreateContextual_NumericShape() throws JsonMappingException {
        JsonFormat.Value mockFormat = mock(JsonFormat.Value.class);
        when(mockFormat.getShape()).thenReturn(JsonFormat.Shape.NUMBER_INT);
        testSerializer.setMockFormat(mockFormat);

        JsonSerializer<?> result = testSerializer.createContextual(mockSerializers, mockProperty);

        assertTrue("Should return a new serializer with timestamp=true", result instanceof TestDateTimeSerializer);
        TestDateTimeSerializer resultSerializer = (TestDateTimeSerializer) result;
        assertTrue(resultSerializer._asTimestamp(mockSerializers));
    }

    @Test
    public void testCreateContextual_StringShapeWithPattern() throws JsonMappingException {
        JsonFormat.Value mockFormat = mock(JsonFormat.Value.class);
        when(mockFormat.getShape()).thenReturn(JsonFormat.Shape.STRING);
        when(mockFormat.hasPattern()).thenReturn(true);
        when(mockFormat.getPattern()).thenReturn("yyyy-MM-dd");
        when(mockFormat.hasLocale()).thenReturn(false);
        when(mockFormat.hasTimeZone()).thenReturn(false);
        testSerializer.setMockFormat(mockFormat);

        JsonSerializer<?> result = testSerializer.createContextual(mockSerializers, mockProperty);

        assertTrue(result instanceof TestDateTimeSerializer);
        TestDateTimeSerializer resultSerializer = (TestDateTimeSerializer) result;
        // Accessing private field via reflection or checking behavior via type
        // Since we can't easily check the private DateFormat field, we verify it doesn't crash and returns a new instance
        assertNotSame(testSerializer, resultSerializer);
    }

    @Test
    public void testCreateContextual_StringShapeWithLocaleAndTZ() throws JsonMappingException {
        JsonFormat.Value mockFormat = mock(JsonFormat.Value.class);
        when(mockFormat.getShape()).thenReturn(JsonFormat.Shape.STRING);
        when(mockFormat.hasPattern()).thenReturn(false);
        when(mockFormat.hasLocale()).thenReturn(true);
        when(mockFormat.getLocale()).thenReturn(Locale.FRANCE);
        when(mockFormat.hasTimeZone()).thenReturn(true);
        when(mockFormat.getTimeZone()).thenReturn(TimeZone.getTimeZone("GMT"));
        testSerializer.setMockFormat(mockFormat);

        JsonSerializer<?> result = testSerializer.createContextual(mockSerializers, mockProperty);

        assertTrue(result instanceof TestDateTimeSerializer);
        assertNotSame(testSerializer, result);
    }

    @Test
    public void testCreateContextual_FallbackToSerializers() throws JsonMappingException {
        JsonFormat.Value mockFormat = mock(JsonFormat.Value.class);
        when(mockFormat.getShape()).thenReturn(JsonFormat.Shape.STRING);
        when(mockFormat.hasPattern()).thenReturn(false);
        when(mockFormat.hasLocale()).thenReturn(false);
        when(mockFormat.hasTimeZone()).thenReturn(false);
        testSerializer.setMockFormat(mockFormat);

        // The code logic: if shape is STRING, it enters the block even if hasPattern/Locale/TZ are false
        // because of (shape == JsonFormat.Shape.STRING) || ...

        JsonSerializer<?> result = testSerializer.createContextual(mockSerializers, mockProperty);
        assertTrue(result instanceof TestDateTimeSerializer);
    }

    @Test
    public void testCreateContextual_OtherShapeReturnsThis() throws JsonMappingException {
        // If shape is not numeric and not STRING and no pattern/locale/tz
        JsonFormat.Value mockFormat = mock(JsonFormat.Value.class);
        when(mockFormat.getShape()).thenReturn(JsonFormat.Shape.OBJECT);
        when(mockFormat.hasPattern()).thenReturn(false);
        when(mockFormat.hasLocale()).thenReturn(false);
        when(mockFormat.hasTimeZone()).thenReturn(false);
        testSerializer.setMockFormat(mockFormat);

        JsonSerializer<?> result = testSerializer.createContextual(mockSerializers, mockProperty);
        assertSame("Should return this if none of the conditions for custom format are met", testSerializer, result);
    }
}
